-- =========================================================
-- EXTENSÕES
-- =========================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =========================================================
-- ENUMS
-- =========================================================

CREATE TYPE status_conta_enum AS ENUM (
    'ATIVA',
    'BLOQUEADA',
    'ENCERRADA',
    'PENDENTE'
);

CREATE TYPE tipo_transacao_enum AS ENUM (
    'DEPOSITO',
    'SAQUE',
    'TRANSFERENCIA',
    'PAGAMENTO',
    'CASHBACK',
    'EMPRESTIMO',
    'FATURA'
);

CREATE TYPE status_transacao_enum AS ENUM (
    'PENDENTE',
    'PROCESSANDO',
    'CONCLUIDA',
    'FALHOU',
    'CANCELADA'
);

CREATE TYPE status_cartao_enum AS ENUM (
    'ATIVO',
    'BLOQUEADO',
    'CANCELADO'
);

CREATE TYPE status_fatura_enum AS ENUM (
    'ABERTA',
    'PAGA',
    'ATRASADA',
    'PARCIAL'
);

CREATE TYPE status_emprestimo_enum AS ENUM (
    'PENDENTE',
    'APROVADO',
    'RECUSADO',
    'QUITADO',
    'EM_ANDAMENTO'
);

-- =========================================================
-- USUARIOS
-- =========================================================

CREATE TABLE usuarios (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    nome VARCHAR(150) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    telefone VARCHAR(20) NOT NULL UNIQUE,
    cpf CHAR(11) NOT NULL UNIQUE,

    senha_hash TEXT NOT NULL,

    data_nascimento DATE NOT NULL,

    score_atual INTEGER NOT NULL DEFAULT 0,

    status_conta status_conta_enum NOT NULL DEFAULT 'PENDENTE',

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),
    atualizado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_score_positivo
        CHECK (score_atual >= 0)
);

CREATE INDEX idx_usuarios_email
ON usuarios(email);

CREATE INDEX idx_usuarios_cpf
ON usuarios(cpf);

CREATE INDEX idx_usuarios_status
ON usuarios(status_conta);

-- =========================================================
-- CONTAS
-- =========================================================

CREATE TABLE contas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL UNIQUE,

    saldo NUMERIC(15,2) NOT NULL DEFAULT 0,
    limite_credito NUMERIC(15,2) NOT NULL DEFAULT 0,

    agencia VARCHAR(10) NOT NULL,
    numero_conta VARCHAR(20) NOT NULL UNIQUE,

    status status_conta_enum NOT NULL DEFAULT 'ATIVA',

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_conta_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_saldo
        CHECK (saldo >= 0),

    CONSTRAINT chk_limite
        CHECK (limite_credito >= 0)
);

CREATE INDEX idx_contas_usuario
ON contas(usuario_id);

CREATE INDEX idx_contas_numero
ON contas(numero_conta);

-- =========================================================
-- SCORE OPERACIONAL
-- =========================================================

CREATE TABLE score_operacional (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    pontuacao INTEGER NOT NULL,

    classificacao VARCHAR(50) NOT NULL,

    percentual_ranking NUMERIC(5,2) NOT NULL,

    atualizado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_score_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_pontuacao
        CHECK (pontuacao >= 0)
);

CREATE INDEX idx_score_usuario
ON score_operacional(usuario_id);

CREATE INDEX idx_score_pontuacao
ON score_operacional(pontuacao DESC);

-- =========================================================
-- HISTORICO SCORE
-- =========================================================

CREATE TABLE historico_score (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    score_id UUID NOT NULL,

    pontuacao_anterior INTEGER NOT NULL,
    pontuacao_nova INTEGER NOT NULL,

    motivo TEXT NOT NULL,

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_historico_score
        FOREIGN KEY (score_id)
        REFERENCES score_operacional(id)
);

CREATE INDEX idx_historico_score_score
ON historico_score(score_id);

-- =========================================================
-- CARTOES
-- =========================================================

CREATE TABLE cartoes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    conta_id UUID NOT NULL,

    numero_mascarado VARCHAR(25) NOT NULL UNIQUE,

    limite_total NUMERIC(15,2) NOT NULL,
    limite_disponivel NUMERIC(15,2) NOT NULL,

    vencimento_fatura SMALLINT NOT NULL,

    status status_cartao_enum NOT NULL DEFAULT 'ATIVO',

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_cartao_conta
        FOREIGN KEY (conta_id)
        REFERENCES contas(id),

    CONSTRAINT chk_limite_total
        CHECK (limite_total >= 0),

    CONSTRAINT chk_limite_disponivel
        CHECK (limite_disponivel >= 0),

    CONSTRAINT chk_vencimento
        CHECK (vencimento_fatura BETWEEN 1 AND 31)
);

CREATE INDEX idx_cartoes_conta
ON cartoes(conta_id);

CREATE INDEX idx_cartoes_status
ON cartoes(status);

-- =========================================================
-- FATURAS
-- =========================================================

CREATE TABLE faturas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    cartao_id UUID NOT NULL,

    valor_total NUMERIC(15,2) NOT NULL,
    valor_pago NUMERIC(15,2) NOT NULL DEFAULT 0,

    vencimento DATE NOT NULL,

    status status_fatura_enum NOT NULL DEFAULT 'ABERTA',

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_fatura_cartao
        FOREIGN KEY (cartao_id)
        REFERENCES cartoes(id),

    CONSTRAINT chk_valor_total
        CHECK (valor_total >= 0),

    CONSTRAINT chk_valor_pago
        CHECK (valor_pago >= 0)
);

CREATE INDEX idx_faturas_cartao
ON faturas(cartao_id);

CREATE INDEX idx_faturas_status
ON faturas(status);

CREATE INDEX idx_faturas_vencimento
ON faturas(vencimento);

-- =========================================================
-- TRANSACOES
-- =========================================================

CREATE TABLE transacoes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    conta_id UUID NOT NULL,

    tipo tipo_transacao_enum NOT NULL,

    valor NUMERIC(15,2) NOT NULL,

    descricao TEXT NOT NULL,

    status status_transacao_enum NOT NULL DEFAULT 'PENDENTE',

    categoria VARCHAR(100),

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_transacao_conta
        FOREIGN KEY (conta_id)
        REFERENCES contas(id),

    CONSTRAINT chk_valor_transacao
        CHECK (valor > 0)
);

CREATE INDEX idx_transacoes_conta
ON transacoes(conta_id);

CREATE INDEX idx_transacoes_tipo
ON transacoes(tipo);

CREATE INDEX idx_transacoes_status
ON transacoes(status);

CREATE INDEX idx_transacoes_data
ON transacoes(criado_em DESC);

CREATE INDEX idx_transacoes_conta_data
ON transacoes(conta_id, criado_em DESC);

-- =========================================================
-- CASHBACK
-- =========================================================

CREATE TABLE cashback (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    valor NUMERIC(15,2) NOT NULL,

    origem VARCHAR(255) NOT NULL,

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_cashback_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_cashback
        CHECK (valor > 0)
);

CREATE INDEX idx_cashback_usuario
ON cashback(usuario_id);

CREATE INDEX idx_cashback_data
ON cashback(criado_em DESC);

-- =========================================================
-- EMPRESTIMOS
-- =========================================================

CREATE TABLE emprestimos (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    valor_solicitado NUMERIC(15,2) NOT NULL,
    valor_aprovado NUMERIC(15,2),

    juros NUMERIC(5,2) NOT NULL,

    parcelas INTEGER NOT NULL,

    status status_emprestimo_enum NOT NULL DEFAULT 'PENDENTE',

    score_utilizado INTEGER NOT NULL,

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_emprestimo_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_valor_solicitado
        CHECK (valor_solicitado > 0),

    CONSTRAINT chk_juros
        CHECK (juros >= 0),

    CONSTRAINT chk_parcelas
        CHECK (parcelas > 0)
);

CREATE INDEX idx_emprestimos_usuario
ON emprestimos(usuario_id);

CREATE INDEX idx_emprestimos_status
ON emprestimos(status);

CREATE INDEX idx_emprestimos_data
ON emprestimos(criado_em DESC);

-- =========================================================
-- PARCELAS EMPRESTIMO
-- =========================================================

CREATE TABLE parcelas_emprestimo (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    emprestimo_id UUID NOT NULL,

    numero_parcela INTEGER NOT NULL,

    valor NUMERIC(15,2) NOT NULL,

    vencimento DATE NOT NULL,

    pago BOOLEAN NOT NULL DEFAULT FALSE,

    pago_em TIMESTAMP,

    CONSTRAINT fk_parcela_emprestimo
        FOREIGN KEY (emprestimo_id)
        REFERENCES emprestimos(id),

    CONSTRAINT chk_numero_parcela
        CHECK (numero_parcela > 0),

    CONSTRAINT chk_valor_parcela
        CHECK (valor > 0)
);

CREATE INDEX idx_parcelas_emprestimo
ON parcelas_emprestimo(emprestimo_id);

CREATE INDEX idx_parcelas_vencimento
ON parcelas_emprestimo(vencimento);

CREATE INDEX idx_parcelas_pago
ON parcelas_emprestimo(pago);

-- =========================================================
-- ROTAS
-- =========================================================

CREATE TABLE rotas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    distancia_km NUMERIC(10,2) NOT NULL,

    entregas INTEGER NOT NULL,

    score_gerado INTEGER NOT NULL,

    data_rota DATE NOT NULL,

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_rota_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_distancia
        CHECK (distancia_km >= 0),

    CONSTRAINT chk_entregas
        CHECK (entregas >= 0)
);

CREATE INDEX idx_rotas_usuario
ON rotas(usuario_id);

CREATE INDEX idx_rotas_data
ON rotas(data_rota DESC);

-- =========================================================
-- ENTREGAS
-- =========================================================

CREATE TABLE entregas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    origem TEXT NOT NULL,
    destino TEXT NOT NULL,

    valor NUMERIC(15,2) NOT NULL,

    duracao_minutos INTEGER NOT NULL,

    concluida_em TIMESTAMP NOT NULL,

    CONSTRAINT fk_entrega_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id),

    CONSTRAINT chk_valor_entrega
        CHECK (valor > 0),

    CONSTRAINT chk_duracao
        CHECK (duracao_minutos > 0)
);

CREATE INDEX idx_entregas_usuario
ON entregas(usuario_id);

CREATE INDEX idx_entregas_data
ON entregas(concluida_em DESC);

-- =========================================================
-- DISPOSITIVOS
-- =========================================================

CREATE TABLE dispositivos (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    ip INET NOT NULL,

    dispositivo VARCHAR(255) NOT NULL,

    ultimo_login TIMESTAMP NOT NULL,

    ativo BOOLEAN NOT NULL DEFAULT TRUE,

    criado_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_dispositivo_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id)
);

CREATE INDEX idx_dispositivos_usuario
ON dispositivos(usuario_id);

CREATE INDEX idx_dispositivos_ativo
ON dispositivos(ativo);

-- =========================================================
-- NOTIFICACOES
-- =========================================================

CREATE TABLE notificacoes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    usuario_id UUID NOT NULL,

    titulo VARCHAR(255) NOT NULL,

    mensagem TEXT NOT NULL,

    lida BOOLEAN NOT NULL DEFAULT FALSE,

    criada_em TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_notificacao_usuario
        FOREIGN KEY (usuario_id)
        REFERENCES usuarios(id)
);

CREATE INDEX idx_notificacoes_usuario
ON notificacoes(usuario_id);

CREATE INDEX idx_notificacoes_lida
ON notificacoes(lida);

CREATE INDEX idx_notificacoes_data
ON notificacoes(criada_em DESC);